"""Money rules for the depot. All amounts are integer cents."""

from __future__ import annotations

import decimal
import tomllib
from dataclasses import dataclass, field
from decimal import Decimal
from fractions import Fraction
from pathlib import Path

DATA_PATH = Path(__file__).resolve().with_name("data.toml")

ROUNDING_MODES = frozenset(
    {
        decimal.ROUND_UP,
        decimal.ROUND_DOWN,
        decimal.ROUND_CEILING,
        decimal.ROUND_FLOOR,
        decimal.ROUND_HALF_UP,
        decimal.ROUND_HALF_DOWN,
        decimal.ROUND_HALF_EVEN,
        decimal.ROUND_05UP,
    }
)


@dataclass
class Terms:
    markup: Decimal
    bulk_threshold: int
    bulk_discount_pct: int
    storage_cents_per_unit_day: int
    transfer_cost_cents_per_unit: int
    late_penalty_pct: int | None = None
    items: dict = field(default_factory=dict)
    demand: dict = field(default_factory=dict)


def _int(x, name, low=None):
    if not isinstance(x, int) or isinstance(x, bool):
        raise ValueError(f"{name} must be an integer")
    if low is not None and x < low:
        raise ValueError(f"{name} must be >= {low}")
    return x


def load_terms(path=DATA_PATH) -> Terms:
    with open(path, "rb") as fh:
        raw = tomllib.load(fh)

    penalty = raw.get("late_penalty_pct")
    if penalty is not None:
        _int(penalty, "late_penalty_pct", 0)
        if penalty > 100:
            raise ValueError("late_penalty_pct must be <= 100")

    items = {}
    for sku, spec in raw.get("items", {}).items():
        items[sku] = {
            "unit_cost": _int(spec["unit_cost"], "unit_cost", 1),
            "reorder_level": _int(spec["reorder_level"], "reorder_level", 0),
            "shelf_life_days": spec.get("shelf_life_days"),
        }

    demand = {}
    for sku, spec in raw.get("demand", {}).items():
        lo = _int(spec["min"], "min", 0)
        hi = _int(spec["max"], "max", lo)
        demand[sku] = (lo, hi)

    return Terms(
        markup=Decimal(str(raw["markup"])),
        bulk_threshold=_int(raw["bulk_threshold"], "bulk_threshold", 1),
        bulk_discount_pct=_int(raw["bulk_discount_pct"], "bulk_discount_pct", 0),
        storage_cents_per_unit_day=_int(raw["storage_cents_per_unit_day"], "storage", 0),
        transfer_cost_cents_per_unit=_int(
            raw["transfer_credit_cents_per_unit"], "transfer_credit_cents_per_unit", 0
        ),
        late_penalty_pct=penalty,
        items=items,
        demand=demand,
    )


def round_cents(value: Decimal, mode: str) -> int:
    """Round a Decimal amount of cents to a whole cent using the depot's rounding mode."""
    return int(value.quantize(Decimal(1), rounding=mode))


def list_price(unit_cost: int, terms: Terms, mode: str) -> int:
    """C08: unit_cost * (1 + markup), rounded to a whole cent."""
    return round_cents(Decimal(unit_cost) * (Decimal(1) + terms.markup), mode)


def sale_amount(price: int, qty: int, terms: Terms, mode: str) -> int:
    """C07 + C09: price * qty, with bulk discount for qty >= bulk_threshold."""
    gross = price * qty
    if qty >= terms.bulk_threshold:
        net = Decimal(gross) * Decimal(100 - terms.bulk_discount_pct) / Decimal(100)
        return round_cents(net, mode)
    return gross


def receipt_cost(unit_cost: int, qty: int) -> int:
    """C05: receiving costs unit_cost * qty."""
    return unit_cost * qty


def late_receipt_cost(unit_cost: int, qty: int, penalty_pct: int, mode: str) -> int:
    """C18 mechanism: a late delivery is paid less by penalty_pct. Only used once the owner sets the percentage."""
    net = Decimal(unit_cost * qty) * Decimal(100 - penalty_pct) / Decimal(100)
    return round_cents(net, mode)


def transfer_cost(qty: int, terms: Terms) -> int:
    """C11: the sending side pays per unit moved."""
    return qty * terms.transfer_cost_cents_per_unit


def storage_cost(units: int, terms: Terms) -> int:
    """C19: storage for every unit held for one day."""
    return units * terms.storage_cents_per_unit_day


def turnover(shipped_units: int, total_held_unit_days: int, n_days: int):
    """C30: units shipped / average units held. None when the average is 0."""
    if n_days <= 0:
        return None
    avg = Fraction(total_held_unit_days, n_days)
    if avg == 0:
        return None
    return float(Fraction(shipped_units) / avg)
