"""Notifications: an ordered log plus the overdraft and reorder rules."""

from __future__ import annotations


class EventLog:
    def __init__(self):
        self._items: list[tuple] = []

    def emit(self, *args):
        self._items.append(tuple(args))

    def all(self):
        return list(self._items)

    def to_list(self):
        return [list(t) for t in self._items]

    @classmethod
    def from_list(cls, rows):
        if not isinstance(rows, list):
            raise ValueError("log must be a list")
        log = cls()
        for row in rows:
            if not isinstance(row, list) or not row or not isinstance(row[0], str):
                raise ValueError("bad log entry")
            log._items.append(tuple(row))
        return log


def check_overdrawn(cash, log):
    """C20: OVERDRAWN is emitted while cash is below 0 at the advance_day check."""
    if cash < 0:
        log.emit("OVERDRAWN")


def update_reorder(log, armed, key, stock, level, shipped):
    """C14: REORDER(sku, wh) once per dip to or below level.

    `armed` holds keys already reported. A key is disarmed once stock rises
    above the level. A key is reported only when a shipment leaves stock at
    or below the level and it is not already reported.
    """
    if stock > level:
        armed.discard(key)
    elif shipped and key not in armed:
        armed.add(key)
        log.emit("REORDER", key[0], key[1])
