"""Supplier reliability (C15) and suspension (C17)."""

from __future__ import annotations

INITIAL_RELIABILITY = 3
MIN_RELIABILITY = 0
MAX_RELIABILITY = 5
SUSPENDED_AT_OR_BELOW = 1
REINSTATED_RELIABILITY = 2


class SupplierBook:
    def __init__(self):
        self._rel: dict[str, int] = {}

    def ensure(self, name):
        self._rel.setdefault(name, INITIAL_RELIABILITY)

    def exists(self, name):
        return name in self._rel

    def reliability(self, name):
        return self._rel[name]

    def is_suspended(self, name):
        return self._rel[name] <= SUSPENDED_AT_OR_BELOW

    def record_delivery(self, name, on_time):
        """Apply C15. Returns True only when this delivery makes the supplier newly suspended."""
        before = self._rel[name]
        after = before + (1 if on_time else -1)
        after = min(MAX_RELIABILITY, max(MIN_RELIABILITY, after))
        self._rel[name] = after
        return before > SUSPENDED_AT_OR_BELOW and after <= SUSPENDED_AT_OR_BELOW

    def reinstate(self, name):
        self._rel[name] = REINSTATED_RELIABILITY

    def to_dict(self):
        return dict(self._rel)

    @classmethod
    def from_dict(cls, d):
        if not isinstance(d, dict):
            raise ValueError("suppliers must be an object")
        book = cls()
        for name, rel in d.items():
            if not isinstance(name, str) or not name:
                raise ValueError("bad supplier name")
            if not isinstance(rel, int) or isinstance(rel, bool):
                raise ValueError("bad reliability")
            if not MIN_RELIABILITY <= rel <= MAX_RELIABILITY:
                raise ValueError("reliability out of range")
            book._rel[name] = rel
        return book
