"""Depot: multi-warehouse inventory and cash ledger. All money is integer cents."""

from __future__ import annotations

import copy
import json

import money
from events import EventLog, check_overdrawn, update_reorder
from suppliers import SupplierBook

SAVE_VERSION = 1

# Attributes that make up the mutable state. Snapshots copy exactly these.
_MUTABLE = (
    "_cash",
    "_day",
    "_items",
    "_lots",
    "_net_shipped",
    "_shipments",
    "_held",
    "_armed",
    "_suppliers",
    "_orders",
    "_next_order",
    "_log",
)


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


def _is_int(x):
    return isinstance(x, int) and not isinstance(x, bool)


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode, terms=None):
        whs = list(warehouses)
        if not whs or len(set(whs)) != len(whs) or not all(isinstance(w, str) and w for w in whs):
            raise DepotError("BAD_CONFIG")
        if not isinstance(capacities, dict) or set(capacities) != set(whs):
            raise DepotError("BAD_CONFIG")
        if not all(_is_int(capacities[w]) and capacities[w] >= 0 for w in whs):
            raise DepotError("BAD_CONFIG")
        if not _is_int(opening_cash):
            raise DepotError("BAD_CONFIG")
        if not (isinstance(rounding_mode, str) and rounding_mode in money.ROUNDING_MODES):
            raise DepotError("BAD_CONFIG")

        self._warehouses = tuple(whs)
        self._capacities = {w: capacities[w] for w in whs}
        self._mode = rounding_mode
        self._terms = terms if terms is not None else money.load_terms()

        self._cash = opening_cash
        self._day = 0
        self._items = {}
        self._lots = {}          # (sku, wh) -> [[day, qty], ...] oldest first
        self._net_shipped = {}   # sku -> units shipped minus units returned
        self._shipments = []     # [[day, qty], ...]
        self._held = []          # [[day, units_held], ...] recorded by advance_day
        self._armed = set()      # (sku, wh) keys already reported as REORDER
        self._suppliers = SupplierBook()
        self._orders = {}
        self._next_order = 1
        self._log = EventLog()

        self._undo = None
        self._undo_blocked = False

    # ----------------------------------------------------------------- properties

    @property
    def cash(self):
        return self._cash

    @property
    def day(self):
        return self._day

    # ----------------------------------------------------------- snapshot/undo

    def _snapshot(self):
        return {k: copy.deepcopy(getattr(self, k)) for k in _MUTABLE}

    def _restore(self, snap):
        for k, v in snap.items():
            setattr(self, k, v)

    def _mutate(self, body, *args, blocks_undo=False):
        """Run a state-changing body atomically. On error nothing changes."""
        snap = self._snapshot()
        try:
            result = body(*args)
        except BaseException:
            self._restore(snap)
            raise
        if blocks_undo:
            self._undo, self._undo_blocked = None, True
        else:
            self._undo, self._undo_blocked = snap, False
        return result

    def undo(self):
        """C27: revert the last operation exactly, once."""
        if self._undo_blocked:
            raise DepotError("UNDO_BLOCKED")
        if self._undo is None:
            raise DepotError("NOTHING_TO_UNDO")
        snap = self._undo
        self._undo = None
        self._restore(snap)

    # ------------------------------------------------------------ validation

    def _sku(self, sku):
        if not isinstance(sku, str) or sku not in self._items:
            raise DepotError("UNKNOWN_SKU")
        return self._items[sku]

    def _wh(self, wh):
        if not isinstance(wh, str) or wh not in self._capacities:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _qty(qty):
        if not _is_int(qty) or qty <= 0:
            raise DepotError("INVALID_ARGUMENT")

    @staticmethod
    def _cents(x):
        if not _is_int(x) or x < 0:
            raise DepotError("INVALID_ARGUMENT")

    # ----------------------------------------------------------- stock helpers

    def _units(self, sku, wh):
        return sum(q for _, q in self._lots.get((sku, wh), ()))

    def _wh_total(self, wh):
        return sum(self._units(s, wh) for s in self._items)

    def _held_total(self):
        return sum(q for lst in self._lots.values() for _, q in lst)

    def _add_lot(self, sku, wh, qty, day):
        lst = self._lots.setdefault((sku, wh), [])
        lst.append([day, qty])
        lst.sort(key=lambda lot: lot[0])

    def _take(self, sku, wh, qty):
        """Remove qty units FIFO. Caller guarantees enough stock. Returns [[day, qty], ...]."""
        lst = self._lots.get((sku, wh), [])
        taken = []
        remaining = qty
        while remaining > 0:
            lot = lst[0]
            n = min(lot[1], remaining)
            taken.append([lot[0], n])
            lot[1] -= n
            remaining -= n
            if lot[1] == 0:
                lst.pop(0)
        if (sku, wh) in self._lots and not lst:
            del self._lots[(sku, wh)]
        return taken

    def _reorder_update(self, sku, wh, shipped):
        update_reorder(
            self._log,
            self._armed,
            (sku, wh),
            self._units(sku, wh),
            self._items[sku]["reorder_level"],
            shipped,
        )

    def _receive_lots(self, sku, qty, wh, cost):
        if self._cash < 0:
            raise DepotError("OVERDRAWN")
        if self._wh_total(wh) + qty > self._capacities[wh]:
            raise DepotError("CAPACITY")
        if self._cash - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        self._cash -= cost
        self._add_lot(sku, wh, qty, self._day)
        self._reorder_update(sku, wh, shipped=False)

    # ----------------------------------------------------------------- items

    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        return self._mutate(self._do_add_item, sku, unit_cost, reorder_level, shelf_life_days)

    def _do_add_item(self, sku, unit_cost, reorder_level, shelf_life_days):
        if not isinstance(sku, str) or not sku:
            raise DepotError("INVALID_ARGUMENT")
        if not _is_int(unit_cost) or unit_cost <= 0:
            raise DepotError("INVALID_ARGUMENT")
        if not _is_int(reorder_level) or reorder_level < 0:
            raise DepotError("INVALID_ARGUMENT")
        if shelf_life_days is not None and (not _is_int(shelf_life_days) or shelf_life_days < 0):
            raise DepotError("INVALID_ARGUMENT")
        if sku in self._items:
            raise DepotError("DUPLICATE_SKU")
        # C13: only shelf life >= 1 makes an item perishable; 0 means not perishable.
        shelf = shelf_life_days if shelf_life_days else None
        self._items[sku] = {
            "unit_cost": unit_cost,
            "reorder_level": reorder_level,
            "shelf_life_days": shelf,
        }

    def list_price(self, sku):
        item = self._sku(sku)
        return money.list_price(item["unit_cost"], self._terms, self._mode)

    # ----------------------------------------------------------- receiving

    def receive(self, sku, qty, wh):
        return self._mutate(self._do_receive, sku, qty, wh)

    def _do_receive(self, sku, qty, wh):
        item = self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        self._receive_lots(sku, qty, wh, money.receipt_cost(item["unit_cost"], qty))

    def receive_bulk(self, receipts):
        """C24: all-or-nothing list of (sku, qty, wh)."""
        return self._mutate(self._do_receive_bulk, receipts)

    def _do_receive_bulk(self, receipts):
        try:
            rows = list(receipts)
        except TypeError:
            raise DepotError("INVALID_ARGUMENT") from None
        for row in rows:
            if not isinstance(row, (tuple, list)) or len(row) != 3:
                raise DepotError("INVALID_ARGUMENT")
            self._do_receive(*row)

    # ----------------------------------------------------------- shipping

    def ship(self, sku, qty, wh, price):
        return self._mutate(self._do_ship, sku, qty, wh, price)

    def _do_ship(self, sku, qty, wh, price):
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        self._cents(price)
        if self._units(sku, wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        self._take(sku, wh, qty)
        amount = money.sale_amount(price, qty, self._terms, self._mode)
        self._cash += amount
        self._net_shipped[sku] = self._net_shipped.get(sku, 0) + qty
        self._shipments.append([self._day, qty])
        self._reorder_update(sku, wh, shipped=True)
        return amount

    # ----------------------------------------------------------- transfers

    def transfer(self, sku, qty, from_wh, to_wh):
        return self._mutate(self._do_transfer, sku, qty, from_wh, to_wh)

    def _do_transfer(self, sku, qty, from_wh, to_wh):
        self._sku(sku)
        self._wh(from_wh)
        self._wh(to_wh)
        self._qty(qty)
        if from_wh == to_wh:
            raise DepotError("INVALID_ARGUMENT")
        if self._units(sku, from_wh) < qty:
            raise DepotError("INSUFFICIENT_STOCK")
        if self._wh_total(to_wh) + qty > self._capacities[to_wh]:
            raise DepotError("CAPACITY")
        cost = money.transfer_cost(qty, self._terms)
        moved = self._take(sku, from_wh, qty)
        for day, n in moved:
            self._add_lot(sku, to_wh, n, day)  # lots keep their original day
        self._cash -= cost
        self._reorder_update(sku, from_wh, shipped=True)
        self._reorder_update(sku, to_wh, shipped=False)

    # ----------------------------------------------------------- returns

    def return_goods(self, sku, qty, wh, price):
        return self._mutate(self._do_return, sku, qty, wh, price)

    def _do_return(self, sku, qty, wh, price):
        item = self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        self._cents(price)
        if qty > self._net_shipped.get(sku, 0):
            raise DepotError("RETURN_EXCEEDS")
        if item["shelf_life_days"] is not None:
            # OWNER DECISION PENDING: restock or discard returned perishables.
            raise DepotError("PERISHABLE_RETURN_PENDING")
        if self._wh_total(wh) + qty > self._capacities[wh]:
            raise DepotError("CAPACITY")
        self._cash -= price * qty
        self._add_lot(sku, wh, qty, self._day)
        self._net_shipped[sku] -= qty
        self._reorder_update(sku, wh, shipped=False)

    # ----------------------------------------------------------- suppliers

    def place_order(self, supplier, sku, qty, due_day, wh=None):
        return self._mutate(self._do_place_order, supplier, sku, qty, due_day, wh)

    def _do_place_order(self, supplier, sku, qty, due_day, wh):
        self._sku(sku)
        self._qty(qty)
        if not isinstance(supplier, str) or not supplier:
            raise DepotError("INVALID_ARGUMENT")
        if not _is_int(due_day):
            raise DepotError("INVALID_ARGUMENT")
        if wh is None:
            if len(self._warehouses) != 1:
                raise DepotError("WAREHOUSE_REQUIRED")
            wh = self._warehouses[0]
        else:
            self._wh(wh)
        self._suppliers.ensure(supplier)
        if self._suppliers.is_suspended(supplier):
            raise DepotError("SUPPLIER_SUSPENDED")
        oid = self._next_order
        self._next_order += 1
        self._orders[oid] = {
            "id": oid,
            "supplier": supplier,
            "sku": sku,
            "wh": wh,
            "qty": qty,
            "due_day": due_day,
            "status": "open",
        }
        return oid

    def deliver(self, order_id, day):
        return self._mutate(self._do_deliver, order_id, day)

    def _do_deliver(self, order_id, day):
        if not _is_int(day):
            raise DepotError("INVALID_ARGUMENT")
        o = self._orders.get(order_id) if _is_int(order_id) else None
        if o is None:
            raise DepotError("UNKNOWN_ORDER")
        if o["status"] != "open":
            raise DepotError("ORDER_CLOSED")
        unit_cost = self._items[o["sku"]]["unit_cost"]
        late = day > o["due_day"]
        if late:
            pct = self._terms.late_penalty_pct
            if pct is None:
                # OWNER DECISION PENDING (C18): late-penalty percentage not set.
                raise DepotError("LATE_PENALTY_UNDECIDED")
            cost = money.late_receipt_cost(unit_cost, o["qty"], pct, self._mode)
        else:
            cost = money.receipt_cost(unit_cost, o["qty"])
        self._receive_lots(o["sku"], o["qty"], o["wh"], cost)
        o["status"] = "delivered"
        if self._suppliers.record_delivery(o["supplier"], on_time=not late):
            self._log.emit("SUPPLIER_SUSPENDED", o["supplier"])

    def reinstate(self, supplier):
        return self._mutate(self._do_reinstate, supplier)

    def _do_reinstate(self, supplier):
        if not isinstance(supplier, str) or not self._suppliers.exists(supplier):
            raise DepotError("UNKNOWN_SUPPLIER")
        self._suppliers.reinstate(supplier)

    def reliability(self, supplier):
        if not isinstance(supplier, str) or not self._suppliers.exists(supplier):
            raise DepotError("UNKNOWN_SUPPLIER")
        return self._suppliers.reliability(supplier)

    # ----------------------------------------------------------- audit & report

    def audit(self, counts):
        """C22: compares the given (sku, wh) counts with the ledger and logs mismatches."""
        return self._mutate(self._do_audit, counts)

    def _do_audit(self, counts):
        if not isinstance(counts, dict):
            raise DepotError("INVALID_ARGUMENT")
        if not counts:
            raise DepotError("EMPTY_AUDIT")
        for key, counted in counts.items():
            if not (isinstance(key, tuple) and len(key) == 2):
                raise DepotError("INVALID_ARGUMENT")
            sku, wh = key
            self._sku(sku)
            self._wh(wh)
            self._cents(counted)
        for key in sorted(counts):
            sku, wh = key
            ledger = self._units(sku, wh)
            counted = counts[key]
            if ledger != counted:
                self._log.emit("AUDIT_MISMATCH", sku, wh, ledger, counted)

    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is None:
            return sum(self._units(sku, w) for w in self._warehouses)
        self._wh(wh)
        return self._units(sku, wh)

    def report(self):
        rows = []
        for sku in sorted(self._items):
            unit_cost = self._items[sku]["unit_cost"]
            for wh in sorted(self._warehouses):
                units = self._units(sku, wh)
                rows.append((sku, wh, units, units * unit_cost))
        return rows

    def notifications(self):
        return self._log.all()

    # ----------------------------------------------------------- turnover

    def turnover(self, start_day, end_day):
        """C30: units shipped in [start_day, end_day] / average units held on recorded days in that range."""
        if not _is_int(start_day) or not _is_int(end_day):
            raise DepotError("INVALID_ARGUMENT")
        shipped = sum(q for d, q in self._shipments if start_day <= d <= end_day)
        samples = [u for d, u in self._held if start_day <= d <= end_day]
        return money.turnover(shipped, sum(samples), len(samples))

    # ----------------------------------------------------------- the day

    def advance_day(self):
        self._mutate(self._do_advance, blocks_undo=True)

    def _do_advance(self):
        # C21 order: storage charge, then expiry, then overdrawn check.
        held = self._held_total()
        self._held.append([self._day, held])
        self._cash -= money.storage_cost(held, self._terms)

        # C13: expiry for perishable items. Lots older than shelf life are discarded.
        for sku in sorted(self._items):
            shelf = self._items[sku]["shelf_life_days"]
            if shelf is None:
                continue
            for wh in sorted(self._warehouses):
                lst = self._lots.get((sku, wh))
                if not lst:
                    continue
                keep = []
                expired = 0
                for day, qty in lst:
                    if self._day - day > shelf:
                        expired += qty
                    else:
                        keep.append([day, qty])
                if expired:
                    self._log.emit("EXPIRY", sku, wh, expired)
                if keep:
                    self._lots[(sku, wh)] = keep
                else:
                    del self._lots[(sku, wh)]

        check_overdrawn(self._cash, self._log)
        self._day += 1

    # ----------------------------------------------------------- save / load

    def save(self):
        data = {
            "version": SAVE_VERSION,
            "warehouses": list(self._warehouses),
            "capacities": dict(self._capacities),
            "cash": self._cash,
            "day": self._day,
            "items": {sku: dict(spec) for sku, spec in self._items.items()},
            "lots": [
                [sku, wh, [list(lot) for lot in self._lots[(sku, wh)]]]
                for (sku, wh) in sorted(self._lots)
            ],
            "net_shipped": dict(self._net_shipped),
            "shipments": [list(x) for x in self._shipments],
            "held": [list(x) for x in self._held],
            "armed": [[sku, wh] for sku, wh in sorted(self._armed)],
            "suppliers": self._suppliers.to_dict(),
            "orders": [dict(self._orders[k]) for k in sorted(self._orders)],
            "next_order": self._next_order,
            "log": self._log.to_list(),
        }
        return json.dumps(data, sort_keys=True)

    def load(self, s):
        """C28: replaces state from save(). Bad input gives BAD_SAVE and changes nothing."""
        return self._mutate(self._do_load, s)

    def _do_load(self, s):
        try:
            data = json.loads(s)
            parsed = _parse_state(data, self._warehouses, self._capacities)
        except (TypeError, ValueError, KeyError, AttributeError, IndexError):
            raise DepotError("BAD_SAVE") from None
        for k, v in parsed.items():
            setattr(self, k, v)


def _need_int(x, low=None):
    if not _is_int(x) or (low is not None and x < low):
        raise ValueError("bad integer")
    return x


def _need_list(x):
    if not isinstance(x, list):
        raise ValueError("expected list")
    return x


def _need_dict(x):
    if not isinstance(x, dict):
        raise ValueError("expected object")
    return x


def _parse_state(data, warehouses, capacities):
    """Validate a decoded save. Returns the new attribute values or raises ValueError."""
    data = _need_dict(data)
    if _need_int(data.get("version")) != SAVE_VERSION:
        raise ValueError("unknown version")
    if data.get("warehouses") != list(warehouses):
        raise ValueError("warehouses differ")
    if data.get("capacities") != dict(capacities):
        raise ValueError("capacities differ")

    cash = _need_int(data["cash"])
    day = _need_int(data["day"], 0)

    items = {}
    for sku, spec in _need_dict(data["items"]).items():
        spec = _need_dict(spec)
        unit_cost = _need_int(spec["unit_cost"], 1)
        reorder = _need_int(spec["reorder_level"], 0)
        shelf = spec["shelf_life_days"]
        if shelf is not None:
            shelf = _need_int(shelf, 1)
        items[sku] = {"unit_cost": unit_cost, "reorder_level": reorder, "shelf_life_days": shelf}

    def known_sku(sku):
        if not isinstance(sku, str) or sku not in items:
            raise ValueError("unknown sku")
        return sku

    def known_wh(wh):
        if not isinstance(wh, str) or wh not in warehouses:
            raise ValueError("unknown warehouse")
        return wh

    lots = {}
    for row in _need_list(data["lots"]):
        if not isinstance(row, list) or len(row) != 3:
            raise ValueError("bad lots row")
        sku = known_sku(row[0])
        wh = known_wh(row[1])
        if (sku, wh) in lots:
            raise ValueError("duplicate lots")
        lst = []
        for pair in _need_list(row[2]):
            if not isinstance(pair, list) or len(pair) != 2:
                raise ValueError("bad lot")
            lst.append([_need_int(pair[0], 0), _need_int(pair[1], 1)])
        if not lst:
            raise ValueError("empty lot list")
        lst.sort(key=lambda lot: lot[0])
        lots[(sku, wh)] = lst

    net = {}
    for sku, n in _need_dict(data["net_shipped"]).items():
        net[known_sku(sku)] = _need_int(n, 0)

    def pairs(rows):
        out = []
        for row in _need_list(rows):
            if not isinstance(row, list) or len(row) != 2:
                raise ValueError("bad pair")
            out.append([_need_int(row[0], 0), _need_int(row[1], 0)])
        return out

    shipments = pairs(data["shipments"])
    held = pairs(data["held"])

    armed = set()
    for row in _need_list(data["armed"]):
        if not isinstance(row, list) or len(row) != 2:
            raise ValueError("bad armed row")
        armed.add((known_sku(row[0]), known_wh(row[1])))

    book = SupplierBook.from_dict(data["suppliers"])

    orders = {}
    for row in _need_list(data["orders"]):
        row = _need_dict(row)
        oid = _need_int(row["id"], 1)
        if oid in orders:
            raise ValueError("duplicate order id")
        if row["status"] not in ("open", "delivered"):
            raise ValueError("bad order status")
        supplier = row["supplier"]
        if not isinstance(supplier, str) or not supplier or not book.exists(supplier):
            raise ValueError("bad order supplier")
        orders[oid] = {
            "id": oid,
            "supplier": supplier,
            "sku": known_sku(row["sku"]),
            "wh": known_wh(row["wh"]),
            "qty": _need_int(row["qty"], 1),
            "due_day": _need_int(row["due_day"]),
            "status": row["status"],
        }
    next_order = _need_int(data["next_order"], 1)
    if orders and next_order <= max(orders):
        raise ValueError("next_order too small")

    log = EventLog.from_list(data["log"])

    return {
        "_cash": cash,
        "_day": day,
        "_items": items,
        "_lots": lots,
        "_net_shipped": net,
        "_shipments": shipments,
        "_held": held,
        "_armed": armed,
        "_suppliers": book,
        "_orders": orders,
        "_next_order": next_order,
        "_log": log,
    }
