"""Demand simulation (C29). Uses only a seeded RNG, so the same seed gives the same orders."""

from __future__ import annotations

import random

import money


def simulate(days, seed):
    """Return one list of (sku, qty) orders per day. Zero-quantity draws are not orders and are skipped."""
    if not isinstance(days, int) or isinstance(days, bool) or days < 0:
        raise ValueError("days must be a non-negative integer")
    terms = money.load_terms()
    rng = random.Random(seed)
    result = []
    for _ in range(days):
        orders = []
        for sku, (lo, hi) in terms.demand.items():  # data-table order
            qty = rng.randint(lo, hi)
            if qty > 0:
                orders.append((sku, qty))
        result.append(orders)
    return result
